-- Function: public.fn_get_users_hierarchy
-- Backup generated on 2026-10-25 20:33:45

CREATE OR REPLACE FUNCTION public.fn_get_users_hierarchy(p_tenant_id uuid)  RETURNS TABLE(user_id uuid, email character varying, display_name character varying, is_active boolean, created_at timestamp with time zone, organization_name character varying, classroom_name character varying, associated_children_count integer, assigned_roles character varying[])  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     WITH user_role_agg AS (         SELECT comb.user_id, array_agg(DISTINCT r.name::VARCHAR) as roles, MAX(o.name) as org_name         FROM (             SELECT ur.user_id, ur.role_id, NULL::UUID as org_id FROM user_roles ur             UNION ALL             SELECT uor.user_id, uor.role_id, uor.organization_id as org_id FROM user_organization_roles uor         ) comb         JOIN roles r ON comb.role_id = r.id         LEFT JOIN organizations o ON o.id = comb.org_id         GROUP BY comb.user_id     ),     classroom_agg AS (         SELECT ct.user_id, MAX(c.name) as c_name         FROM classroom_teachers ct         JOIN classrooms c ON c.id = ct.classroom_id         GROUP BY ct.user_id     ),     parent_agg AS (         SELECT fr.user_id, COUNT(fr.child_id)::int as child_count         FROM family_relationships fr         GROUP BY fr.user_id     )     SELECT         u.id as user_id,         u.email::VARCHAR,         COALESCE(NULLIF(TRIM(u.display_name), ''), NULLIF(TRIM(u.first_name || ' ' || u.last_name), ''), u.email)::VARCHAR as display_name,         u.is_active,         u.created_at,         ura.org_name::VARCHAR as organization_name,         cla.c_name::VARCHAR as classroom_name,         COALESCE(pa.child_count, 0) as associated_children_count,         COALESCE(ura.roles, ARRAY[]::VARCHAR[]) as assigned_roles     FROM users u     LEFT JOIN user_role_agg ura ON ura.user_id = u.id     LEFT JOIN classroom_agg cla ON cla.user_id = u.id     LEFT JOIN parent_agg pa ON pa.user_id = u.id     WHERE p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR u.tenant_id = p_tenant_id     ORDER BY u.first_name, u.last_name; END; $function$ ;
